"""v3.4 -> v3.5 Chinese manuscript revision (synchronised with 75_revise_en_v3_5.py)."""
import io, os, re, sys

BASE = r"D:\龙虾文档\2026-11-02-09-16-41\ESCC_endo"
PATH = os.path.join(BASE, "11_manuscript", "manuscript_zh.md")
s = io.open(PATH, encoding="utf-8").read()
lines = s.splitlines()
N = [0]


def L(prefix, new, tag=""):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    if len(idx) != 1:
        raise SystemExit("[FAIL] line %s: expected 1, found %d :: %r"
                         % (tag or prefix[:30], len(idx), prefix[:60]))
    lines[idx[0]] = new
    N[0] += 1


L("# 食管鳞状细胞癌的内皮状态重塑",
  "# 食管鳞状细胞癌的内皮状态构成：静脉型占比降低、尖端样富集与候选干扰素反应性状态")

L("**背景**　食管鳞状细胞癌",
  "**背景**　食管鳞状细胞癌（esophageal squamous cell carcinoma，ESCC）的内皮状态已有图谱级描述，但更精细的转录状态分层、小样本癌旁对照下的稳健性及免疫相关转录模式仍待厘清。")

L("**方法**　我们重新分析了",
  "**方法**　重新分析 GSE160269 的 CD45⁻ 内皮区室（11,267 个细胞，质控与去污染后保留 9,531 个；60 例肿瘤、4 例癌旁非恶性文库），以 Seurat 与 harmony 处理，按经典标志基因定义九个内皮状态。因 4 例肿瘤与 4 例癌旁来自同一批患者，主要比较采用 56 例未配对肿瘤与 4 例癌旁的精确双侧 Mann–Whitney 检验；4 对配对样本仅报告方向，合并的 60 对 4 比较保留为敏感性分析。差异表达用 limma，富集用 clusterProfiler；内皮–T 细胞配体–受体转录本丰度以 CellChat 在合并细胞上评估。尖端细胞特征衍生的 23 基因评分在三个 bulk 队列中评估：GSE53625（179 对）用嵌套、按患者分组交叉验证，GSE20347（17 对）与 GSE45670（28 例肿瘤、10 例癌旁）用不作重新拟合的全队列描述性模型。")

L("**结果**　基于 4 例癌旁文库",
  "**结果**　主要比较中，静脉型内皮中位占比由癌旁 74.8% 降至肿瘤 28.5%（BH q = 0.0005）；尖端样由 0.2% 升至 14.8%（q = 0.0007），基质重塑型由 0 升至 13.8%（q = 0.0005），候选、探索性干扰素反应性状态由 0 升至 4.6%（q = 0.0007）。静脉型 Hodges–Lehmann 位移 −44.8 个百分点（95% CI −61.2 至 −28.7）。逐一剔除癌旁文库保留全部 16 项预设方向（联合 BH q = 0.0010–0.0025）。干扰素反应性状态稳定性较弱：仅 1 例癌旁检出（0.44%），在每样本 20 与 30 个细胞的等细胞数下抽样中分别仅 16% 与 85.5% 的重复通过校正，4 对配对方向不一致。尖端细胞携带细胞外基质程序（422 个基因中 37 个，校正 P = 2.0 × 10⁻¹²）。CellChat 给出的是合并的转录本水平配体–受体表达排序，不构成肿瘤特异通讯或抗原提呈证据；MHC I 类与 MIF 居前。23 基因评分在 GSE53625 的嵌套折外 AUC 为 0.9998（95% CI 0.9993–1.0000），在两个外部队列为 1.000 与 0.989，但匹配的随机 23 基因集几乎同样高；评分在 GSE53625（每标准差 HR 1.04，P = 0.686）与 TCGA-ESCA 中均无预后价值。两个外部单细胞队列共 7 对配对样本支持构成改变的方向，但不支持绝对比例。")

L("**结论**　ESCC 肿瘤与癌旁黏膜",
  "**结论**　在 4 例癌旁文库、且主要比较限定于 56 例未配对肿瘤的前提下，ESCC 肿瘤与癌旁黏膜的内皮状态构成不同：静脉型占比降低，尖端样与基质重塑型占比升高；候选干扰素反应性状态的稳定性低于前两者。这些观察属描述性，尚无诊断或预后用途。")

L("ESCC 的肿瘤与配对癌旁黏膜之间是否存在内皮状态差异",
  "既往 ESCC 单细胞图谱已经比较过肿瘤与癌旁非恶性黏膜的内皮细胞。本研究重新分析的数据集解析了 42 类细胞（含 6 个内皮亚型），报告 NEC1/2 在癌旁组织中占优势、TEC1–3 主要见于肿瘤，并把 TEC 占比与调节性及耗竭 T 细胞比例做了关联[14]；另一项 ESCC 图谱刻画了免疫与基质异质性[15]，还有一项比较了上、下段食管肿瘤的内皮亚群与胶原/层粘连蛋白血管生成程序[13]。尚未完成的是：对 CD45⁻ 内皮区室作更精细的转录状态分层，区分静脉型、尖端样、基质重塑与干扰素反应性程序，并系统评估 4 例癌旁文库、配对设计与闭合成分约束对差异估计的影响。因此本文在既有图谱基础上重新解析构成、量化样本不平衡与成分偏倚下的稳健性，并检验尖端来源表达评分的特异性与临床局限。")

L("因此我们回到一份已发表的 ESCC 单细胞数据集",
  "我们回到这份已发表的 ESCC 单细胞数据集——原作者以 CD45 分选把细胞分为免疫与非免疫两部分[14]——分离内皮细胞群，提出三个问题。其一，在尊重文库配对结构的前提下，这些细化状态的相对占比在肿瘤与癌旁之间是否不同。其二，占比升高的状态携带何种转录程序。其三，这些状态伴随哪些免疫相关转录模式，肿瘤–癌旁表达评分是否具备超出一般差异表达的特异性。")

L("内皮细胞每状态最多降采样至 350 个",
  "内皮细胞每状态最多降采样至 350 个，另从 GSE160269 的 T 细胞矩阵（69,278 个细胞）中随机抽取 8,000 个 T 细胞。T 细胞状态按标志基因检出判定：CD8（CD8A 或 CD8B）、CD4（CD4 且无 CD8）、调节性 T 细胞（CD4 且 FOXP3 与 IL2RA）、耗竭标志高表达 CD8（CD8 且 PDCD1、HAVCR2、LAG3、TIGIT、TOX 中至少两项阳性）、NK 样（无 CD3D 或 CD3E，但 GNLY、NKG7 或 KLRD1 阳性），以及未满足任何规则的「其他/未分类 T 细胞」。「耗竭标志高表达」仅指与多个抑制性受体相关的转录表型，不等于功能性 T 细胞耗竭[38]。通讯以 CellChat v2 与 CellChatDB.human 推断，采用 triMean，主分析置换 50 次（50 次为本文设定；原始方法的默认值为 100 次）[23]，另以 200 次置换、两个独立内皮降采样种子作稳健性复核。50 次置换下置换 P 值的分辨率为 0.02，6,132 条保留配体–受体对中 6,058 条 P = 0；200 次置换的两个稳健性运行中，6,132–6,144 条里仍有 5,990–6,034 条 P = 0，且全部经 Benjamini-Hochberg 校正后仍显著，MHC I 类、MIF 与 APP 仍为前三条通路。置换检验本身无法区分这些配对，故该列表按「表达的配体–受体对」报告；也不支持对单对作统计学显著性主张（附表 S8）。每组细胞数少于 10 的配对滤除。配体丰度排序对内皮降采样的稳健性以 5 个随机种子核查（附表 S8），5 个种子下 B2M、HLA-B、HLA-A、HLA-C、CD74、PLVAP、HLA-E、PECAM1、CD99、APP、MIF、ICAM1 的排序完全一致。CellChatDB 以复合物各亚基表达量的几何平均近似其表达水平，故任一亚基为零即使该复合物失活；本数据中 ITGAL/ITGB2 主要由 T 细胞表达、内皮几乎为零（ITGB2 平均 0.00），黏附通路排序靠后源于配体表达量级（每细胞平均 UMI 计数）——ICAM1 平均 10.0，而 HLA-A、HLA-B 与 B2M 分别为 33.6、37.5 与 108.6。T 细胞标签按单一互斥优先级赋值，每个细胞只归入一组（NK 样 > 调节性 > 耗竭标志高表达 CD8 > CD8 > CD4 T > 其他/未分类 T）；CD4 与 CD8 双阳性细胞归入 CD8 组。不满足任何规则者归入「其他/未分类 T」，不纳入内皮→T 细胞汇总；8,000 个 T 细胞中 CD8 T 885 个、耗竭标志高表达 CD8 2,937 个、CD4 T 1,047 个、调节性 833 个、NK 样 189 个、其他/未分类 2,109 个。肿瘤来源与癌旁来源的细胞合并进入同一个 CellChat 对象，未按组织来源分层，也未把患者身份作为分组因素；不同患者的细胞被合并后，某患者内皮的配体与另一患者 T 细胞的受体也可能被模型配成一对。因此该结果是合并的转录本水平配体–受体表达谱，不能解读为肿瘤特异通讯、同一组织微环境内的细胞接触或功能性相互作用。")

L("按标志基因将 69,278 个 T 细胞判为",
  "按标志基因将 69,278 个 T 细胞判为 CD8、耗竭标志高表达 CD8、CD4、调节性与 NK 样五组，计算每例患者各组的占比，并以耗竭标志高表达细胞占全部 CD8 的比例作为耗竭程度的指标，避免与 CD8 总量混淆。该指标与内皮九群占比作 Spearman 相关，并在两侧细胞数均充足（内皮 ≥30、T ≥50）的样本中重复。九个状态间的 Spearman 检验用 Benjamini-Hochberg 法校正；47 例亚组按细胞数阈值事后定义，仅作为敏感性分析报告。与 CellChat 的互斥标签不同，患者水平相关分析所用的标志检出计数并不互斥：耗竭标志高表达 CD8 是 CD8 的子集，调节性是 CD4 的子集，一个细胞可计入多个计数。这些重叠计数仅用于计算患者层面占比；耗竭程度定义为 CD8 阳性细胞中至少两项耗竭相关标志阳性者所占比例，属转录表型而非功能测定。")

L("除特别说明外，均采用双侧检验",
  "除特别说明外，均采用双侧检验，并在每个预先定义的检验族内做 Benjamini-Hochberg 校正。肿瘤–癌旁主要比较使用 56 例无配对癌旁的肿瘤与 4 例癌旁非恶性文库，对九个状态占比作精确双侧 Mann–Whitney 检验，BH 检验族即这九次检验。4 例配对肿瘤（P126T、P127T、P128T、P130T，按样本编号与 60 例临床表对应 P126N、P127N、P128N、P130N）仅报告配对方向，不给出 P 值；合并的 60 对 4 比较按同一九次检验族重算，作为敏感性分析。逐一剔除癌旁文库为 4 次剔除 × 4 个预设主要状态 = 16 项探索性比较；BH 校正既在 16 项联合进行，也在每次剔除内对九个状态分别进行，两种口径均见附表 S12。四次剔除是同一假设的重抽样而非四个独立假设，故该检验族与主要比较的九次检验族分开。其余检验族为：九个状态与 T 细胞耗竭的相关、针对五个原始 T 细胞亚群占比的 9 × 5 分析、六个状态与三个分期变量的相关（每个变量六次检验）、CellChat 保留配对，以及附表 S8、S10 中的 Cox 与 Schoenfeld 检验。随机基因与置换对照为经验性对照，不作校正。分期关联只检验图 6 展示的六个状态（尖端、干扰素反应性、基质相关、静脉、毛细血管与动脉）；炎症小静脉、增殖型与淋巴管型未纳入，后两者仅 329 与 34 个细胞，故该阴性结果属选择性分析。四组匹配的随机基因对照各 200 组（合计 800 组）。所有曲线下面积的置信区间来自 2,000 次以患者为单位的 bootstrap 重抽样；非配对的 GSE45670 队列以每个样本为独立重抽样单位。CellChatDB.human 通过表达过滤的 581 条条目与保留的 6,132 条配体–受体对计数对象不同（数据库条目与按发送–接收细胞组解析的配对）。CellChat 的「通讯概率」是各贡献配对的求和无量纲得分，并非概率，可大于 1；图件中统一标为「聚合 CellChat 得分（任意单位）」。中心对数比分析先以 0.5 伪计数替换零值再重新闭合；Dirichlet–多项分布零模型以矩估计匹配静脉占比的样本间方差，从候选网格 5、20、50、100、200、400 中选定浓度参数，再按各样本真实细胞总数作多项抽样，每个模型 4,000 次重复，经验单侧 P 值按（1 + 零模型系数不高于观测值的次数）/ 4,001 计算。主要 56 对 4 比较的效应量用 Hodges–Lehmann 双样本位移估计，95% 置信区间来自 2,000 次患者级 bootstrap 重抽样。闭合成分、CLR、Dirichlet–多项分布、保留成纤维样簇与等细胞数下抽样均在全部 60 例肿瘤与 4 例癌旁上计算，作为对原始设计的稳健性核查；主要 P 值与置信区间来自 56 对 4 比较。完整表格见附表 S11、S12。")

L("分析使用 R 4.4.3",
  "分析使用 R 4.4.3（Seurat 5.5.0、harmony 1.2.4、limma 3.62.2、clusterProfiler 4.14.6、CellChat 2.2.0.9001、ComplexHeatmap 2.22.0、SingleR 2.8.0、celldex 1.16.0）与 Python 3.13.14（numpy 2.5.4、pandas 2.3.3、scipy 1.18.1、scikit-learn 1.9.1、statsmodels 0.15.0、lifelines 0.30.3、matplotlib 3.11.2）。完整 sessionInfo 与随机种子清单见附表 S8。分析脚本清单见附表 S12，脚本与处理后对象可向通讯作者合理索取。")

L("**图 1　ESCC 的内皮细胞状态。**",
  "**图 1　ESCC 的内皮细胞状态。**（A）来自 60 例肿瘤与 4 例癌旁非恶性黏膜的 9,531 个内皮细胞的 UMAP 投影，按状态着色；图中状态名采用正文显示名（尖端样、基质重塑、炎症小静脉、干扰素反应性等）。（B）全部 11,267 个内皮细胞的质控：横轴为每细胞检出基因数（对数刻度），纵轴为线粒体读数百分比，虚线为 200、5,000 个基因与 10% 线粒体比例的阈值。剔除的 1,130 个细胞（10.0%）中，1,077 个因线粒体比例超标、53 个因检出基因数超过 5,000。再剔除 606 个带周细胞、成纤维细胞或免疫细胞标志的细胞后，9,531 个细胞进入分析。（C）各状态经典标志基因的表达；点大小表示表达该基因的细胞百分比，颜色表示标度化平均表达。")

L("构成比按闭合成分重算",
  "构成比按闭合成分重算：九个保留状态在每样本合计为 1，未检出的状态记 0。在 56 例未配对肿瘤与 4 例癌旁非恶性文库的主要比较中，静脉型占比中位数由 74.8% 降至 28.5%（精确 Mann–Whitney P = 0.00011，九个状态 BH q = 0.00050；图 2B、2C）。尖端样由 0.2% 升至 14.8%（P = 0.00029，q = 0.00066），基质重塑型由 0 升至 13.8%（P = 0.000074，q = 0.00050），炎症小静脉由 0 升至 9.9%（q = 0.00065），候选干扰素反应性状态由 0 升至 4.6%（P = 0.00039，q = 0.00069）。毛细血管型由 11.6% 降至 6.1%（P = 0.046，q = 0.059，校正后不显著），动脉型无变化（12.1% 对 13.4%，q = 0.62）。该设计下精确检验与渐近检验给出相同的九个校正后判定（附表 S12）。4 对配对肿瘤中，静脉型方向在 3/4 对成立（肿瘤减癌旁：+23.1、−5.0、−19.6 与 −89.5 个百分点），尖端样与干扰素反应性方向各在 2/4 对成立；配对结果不附 P 值。4 例癌旁文库的静脉型占比分别为 57.1%、72.7%、76.9% 与 89.5%（内皮细胞数分别为 56、264、308 与 228）。逐一剔除每例癌旁文库保留全部 16 项预设方向及全部 16 项联合校正判定（q = 0.0010–0.0025）。肿瘤减癌旁的中位数差为：静脉型 −46.4 个百分点（Hodges–Lehmann −44.8，bootstrap 95% CI −61.2 至 −28.7）、尖端样 +14.7（8.6 至 17.0）、基质重塑型 +13.8（10.4 至 15.1）、干扰素反应性 +4.6（3.2 至 6.4）。合并的 60 对 4 敏感性分析方向一致、主要判定不变，但毛细血管型跨过 0.05 边界（精确 q = 0.049）；保留 529 细胞成纤维样簇时同样跨界（q = 0.048）。故毛细血管型属边界结果，不是稳定发现。完整表格见附表 S11、S12。")

L("各肿瘤之间差异很大（图 2A）",
  "各肿瘤之间差异很大（图 2A）。尖端细胞占比从 0 到 60% 不等，干扰素反应性状态在 60 例肿瘤中的 6 例（10%）检测不到。该状态的稳定性低于静脉型与尖端样：仅 1 例癌旁检出，在每样本 20 与 30 个细胞的等细胞数下抽样中分别仅 16% 与 85.5% 的重复通过校正，4 对配对方向不一致，且 GSE203067 中 marker 层面支持方向相反。故本文将其作为候选、探索性状态，而非已验证的独立内皮亚型（附表 S9、S11、S12）。")

L("**图 2　构成重塑。**",
  "**图 2　内皮状态构成。**（A）全部 60 例肿瘤的内皮构成，按静脉型占比降序排列。（B）主要比较所用的 56 例未配对肿瘤与 4 例癌旁非恶性文库中六个主要状态的占比；箱体示中位数与四分位间距，须延伸至 1.5 倍四分位间距。（C）同一比较下各状态占比的中位数。4 例配对肿瘤不纳入（B）、（C）；其配对方向与合并的 60 对 4 敏感性分析见附表 S12。")

L("### 干扰素反应性亚群基本为肿瘤特有",
  "### 候选干扰素反应性状态基本限于肿瘤")

L("干扰素反应性状态共同表达 CXCL9",
  "干扰素反应性状态共同表达 CXCL9、CXCL10、CXCL11 以及 RSAD2 与 IFIT2（图 4A）。其占比在 56 例未配对肿瘤中为 4.6%，癌旁黏膜中位为 0；4 例癌旁中仅 1 例检出该状态（0.44%）。该状态称为「干扰素反应性」，是因为这些转录本不能区分 I 型与 II 型干扰素信号；该名称仅为描述，不确立活化状态或功能上独立的内皮谱系。")

L("在 60 例肿瘤中，干扰素反应性内皮的占比",
  "在全部 60 例肿瘤中（与主要配对设计分开的描述性分析），干扰素反应性内皮占比与该样本 CD8 T 细胞中至少两项耗竭相关标志阳性者的比例呈名义正相关（ρ = 0.28，P = 0.029），与 CD8 总量无关；按九个状态做 Benjamini-Hochberg 校正后最小 FDR 为 0.16，无状态显著。动脉型内皮系数相近（ρ = 0.27，P = 0.036），尖端细胞则无关联（ρ = 0.15，P = 0.26）。在事后定义的 47 例充分采样亚组（内皮 ≥30、T ≥50）中关联更强（ρ = 0.47，P = 0.0009，FDR = 0.008；附图 S2），因该亚组系看到数据后划定，仅作敏感性分析。针对五个原始 T 亚群占比的 9 × 5 分析最小 FDR 为 0.39（附表 S8）。")

L("**附图 S2　内皮状态占比与 CD8 耗竭程度的关联。**",
  "**附图 S2　内皮状态占比与 CD8 耗竭相关转录表型的关联。**（A）60 例肿瘤中干扰素反应性内皮占比与 CD8 T 细胞中耗竭标志高表达者比例的关系（Spearman ρ = 0.28，名义 P = 0.029，九个状态校正后 FDR = 0.16）。（B）事后定义的 47 例充分采样亚组（内皮 ≥30、T ≥50；ρ = 0.47，P = 0.0009，FDR = 0.008），仅作敏感性分析。（C）九个内皮状态与该指标的相关系数；校正后无状态显著（最小 FDR = 0.16），动脉型与干扰素反应性状态接近（ρ = 0.27，P = 0.036）。该指标指 CD8 细胞中至少两项耗竭相关标志阳性者所占比例，属转录表型，不等同于功能性耗竭。")

L("**图 4　干扰素反应性内皮。**",
  "**图 4　候选干扰素反应性内皮。**（A）炎症与抗原提呈相关基因在各状态中的表达。（B）该状态相对静脉型内皮上调基因的 GO 富集。（C）各肿瘤中干扰素反应性内皮细胞的占比，纵轴为干扰素反应性占比。该状态属探索性，稳定性低于静脉型与尖端样差异（附表 S9、S11、S12）。")

L("### 合并的配体–受体表达谱以 MHC I 类与 MIF 最高",
  "### 合并的转录本水平配体–受体表达谱")

L("CellChat 在 10,813 个细胞",
  "CellChat 在 10,813 个细胞（内皮 2,813 个、T 细胞 8,000 个）与 581 条数据库配体–受体条目上进行推断，展开为 6,132 条按发送–接收细胞组解析并过滤后保留的配体–受体对；其中 1,556 条连接内皮状态与五个可解释的 T 细胞组。2,109 个未满足任何标志规则的 T 细胞记为「其他/未分类 T」，不纳入内皮→T 细胞汇总。内皮状态指向耗竭标志高表达 CD8 细胞的保留配对数最多（图 5A）。将置换次数提高到 200 并在两个降采样种子下重跑后，MHC I 类、MIF 与 APP 仍为前三条通路（附表 S8）。因肿瘤来源与癌旁来源细胞、以及不同患者的细胞被合并于同一对象，该排序是合并的转录本水平表达谱：既不能识别肿瘤特异的内皮–T 细胞互作，也不要求某配体与其受体来自同一患者或同一组织微环境。")

L("主要通路为 MHC I 类分子",
  "主要通路为 MHC I 类分子（聚合 CellChat 得分 32.3，任意单位，180 对）与 MIF（13.7，80 对），其后为 APP（9.6）、胶原（9.1）与半乳凝素（6.8）（图 5B）。黏附通路排序远低于此：ICAM 贡献 0.84，PECAM1 贡献 0.25。")

L("就单对互作而言，APP–CD74",
  "就单对互作而言，APP–CD74（9.48）、MIF–CD74–CD44（7.29）、MIF–CD74–CXCR4（6.42）与 COL4A2–CD44（5.70）居前，HLA-B、HLA-A、HLA-C 与 HLA-E 指向 CD8A 者紧随其后（4.87、4.81、4.67 与 3.99；图 5C）。上述数值均为求和无量纲 CellChat 得分（任意单位），不是概率。")

L("两点需要强调，且两者都是关于转录本丰度",
  "两点需要强调，且两者都是关于转录本丰度而非功能的陈述。其一，MHC I 类配体–受体对在合并的内皮–T 细胞排序中占主导，II 类对亦存在（聚合得分 6.3）；CD8A 只是共受体，本数据不含肽装载、T 细胞受体与空间信息，该排序不能证明抗原提呈。其二，综述文献指出 MIF–CD74 信号可抑制 CD8 效应功能并有利于髓系抑制[24]，它是合并分析中内皮侧第二强的输出；但本数据既不能把 MIF 归因于体内内皮来源，也不能确立免疫抑制效应。5 个独立降采样种子下配体丰度排序完全一致（附表 S8）。")

L("**图 5　合并分析的内皮–T 细胞配体–受体表达。**",
  "**图 5　合并的转录本水平内皮–T 细胞配体–受体表达。**（A）各内皮状态向五个可解释 T 细胞组保留的表达配体–受体对数；2,109 个「其他/未分类 T」细胞不纳入该汇总。（B）各通路的聚合 CellChat 得分（求和无量纲得分，任意单位）；柱末端数字为该通路包含的配体–受体对数。（C）靶向 CD8 T 细胞的主要配体–受体对，按通路着色。图中「CD8 exhausted」指 CD8 T 细胞至少表达两项耗竭相关标志，属转录表型，不证明功能性耗竭。肿瘤与癌旁、不同患者的细胞被合并分析，故这些配对既非肿瘤特异，也不代表同一患者内的相互作用。黏附配体丰度低于 MHC I 类转录本（附表 S8）。")

L("为把 4 例癌旁置于更广的参照中",
  "为把 4 例癌旁非恶性文库置于更广的参照中，我们在不增加实验的前提下重新分析了三套公开单细胞数据。在两个独立 ESCC 队列共 7 对配对癌旁/肿瘤样本中，标签转移后的静脉型内皮占比在 7/7 对中癌旁高于肿瘤，干扰素反应性占比在 7/7 对中癌旁低于肿瘤（双侧符号检验，P = 0.0156；三个状态间 BH 校正后 q = 0.023）；tip 样内皮在 6/7 对中癌旁低于肿瘤（P = 0.125，q = 0.125）。因期望方向取自发现队列，这些检验属描述性而非确证性。在一个经审编的正常/良性食管–胃内皮图谱（3,951 个内皮细胞）中，作者原始注释以静脉型为最大群体（总体 49.8%，正常供者 51.1%）。但绝对比例跨平台不可复现：在同一标签转移流程下，外部队列癌旁文库的静脉占比为 31.0%–64.6%，而发现队列为 77.7%（其原始人工注释下为 74.8%）；两种标签转移方法的一致率仅 48.8%。这些分析仅为方向性、探索性的敏感性分析，不提供独立的组织学、多重免疫荧光或空间层面对九个内皮状态的验证（附表 S9；附图 S4）。")

L("**附图 S4　仅用公开数据完成的外部单细胞验证。**",
  "**附图 S4　仅用公开数据完成的外部单细胞验证。**（A）经审编的正常/良性食管–胃内皮图谱的作者注释（CELLxGENE，n = 3,951 个内皮细胞）；红色虚线为发现队列 4 例癌旁非恶性文库在同一标签转移流程下的静脉占比中位数（77.7%；原始人工注释下为 74.8%）。（B）表达至少两个尖端样或干扰素反应性状态标志基因的内皮细胞比例；各队列与状态的背景阳性率为 19.8%–93.2%，且 GSE203067 中干扰素反应性状态的 marker 证据方向相反。（C）跨数据集标签转移后的静脉占比（探索性；两种方法一致率 48.8%）。（D）两个独立 ESCC 队列共 7 对配对样本在患者层面的方向；双侧符号检验，三个状态间 BH 校正，期望方向取自发现队列（附表 S9）。N，癌旁非恶性黏膜；T，肿瘤。图中状态名已按图 1–5 的显示名统一。")

L("本文的增量是状态分辨的描述加一条方法学警示",
  "本文的增量是对既有图谱的状态分辨再解析加一条方法学警示，既非首次发现，也非新机制。肿瘤与癌旁之间的内皮构成差异已在本数据所出的图谱[14]及后续 ESCC 内皮研究[13]中报告。我们增加的是：对 CD45⁻ 内皮区室作更精细的转录状态划分，区分静脉型、尖端样、基质重塑、炎症小静脉与干扰素反应性程序，并量化 4 例癌旁文库、配对设计与闭合成分对差异估计的约束。基于 4 例癌旁文库，肿瘤中静脉型占比降低，尖端样与基质重塑型占比升高，动脉型保持不变。尖端细胞的分子内容把静脉程序转录本减少与以胶原、基质金属蛋白酶为核心的基质重塑程序合并在一起，与基底膜重塑相容，但不能证明重塑正在发生。表达 CXCL9、CXCL10 与 CXCL11 的候选干扰素反应性状态，为同一构成差异增添了探索性的免疫维度。")

L("静脉型向尖端细胞的交换是最明确的结果",
  "静脉型与尖端样内皮状态之间的互逆构成位移是最明确的结果。癌旁黏膜的内皮以静脉型为主，尖端细胞几乎不存在；在 56 例未配对肿瘤中，静脉型占比中位由 74.8% 降至 28.5%，尖端样占内皮细胞的 14.8%，动脉型占比不动。由于各状态占比合计为 1，静脉–尖端负相关中有一部分来自闭合效应：中心对数比变换把系数由 −0.61 降为 −0.46，保留观测细胞数的 Dirichlet–多项分布零模型给出的中位值为 −0.25。观测位移超出该零模型（经验 P = 0.0005–0.0062），但我们不把它当作特定表型转换或静脉内皮绝对数量减少的证据；它是相对占比的改变，与跨癌种图谱中报告的尖端细胞富集一致[10]。")

L("就免疫治疗而言，干扰素反应性亚群",
  "就免疫治疗而言，候选干扰素反应性状态值得关注，但本文并未把它确立为独立的内皮亚型。它表达 CXCL9、CXCL10 与 CXCL11，可在实验体系中招募表达 CXCR3 的 CD8 T 细胞[28]，且在癌旁黏膜中基本缺如；其占比在肿瘤之间相差十余倍，且不随分期变化。稳定性弱于静脉型与尖端样差异：仅 1 例癌旁检出该状态，等细胞数下抽样在每样本 20 与 30 个细胞时分别仅 16% 与 85.5% 的重复保留其校正后差异，4 对配对方向不一致，两种标签转移方法一致率仅 48.8%，且 GSE203067 中 marker 层面支持方向相反（附表 S9、S11、S12）。该状态是否与 PD-1 阻断获益相关仅属假说；干扰素-γ 相关表达谱已被提出可作为帕博利珠单抗治疗队列的预测标志，其作者同时提醒该特征是必要但非充分条件[29]，本研究没有免疫治疗队列。其与耗竭标志高表达 CD8 细胞的名义相关在九个状态校正后不显著（最小 FDR = 0.16），动脉型系数相近，较强的结果仅见于事后的 47 例亚组。故本文不提出「招募后失能」的解释。")

L("通讯分析给出了一个我们未曾预料的结果",
  "通讯分析给出了一个我们未曾预料的排序。依据白细胞归巢文献，我们原以为黏附分子会主导内皮输出；CellChat 按配体转录本丰度将 MHC I 类列于首位、MIF 列于第二，ICAM 与 PECAM1 合计不足总量的 3%。这是合并的转录本水平结果：肿瘤与癌旁、不同患者的细胞被合并，某患者内皮的配体与另一患者 T 细胞的受体可能被模型配成一对，而这些细胞并不共享同一组织微环境。该排序不能说明 T 细胞进入是否仍为限速步骤、是否存在肿瘤特异互作，或是否发生抗原提呈；黏附通路靠后也可能只是 ICAM1、PECAM1 转录本丰度低于 MHC I 类配体。中和内皮素 B 受体可解除内皮屏障并通过 ICAM-1 依赖机制增加 T 细胞归巢，这一结论来自实验模型[30]。综述把内皮细胞称为「非专业抗原提呈细胞」[31]并提出肿瘤内皮可充当微环境的免疫「导演」[32]，小鼠或离体研究则把淋巴管内皮 MHC II 类信号[33]与肝窦内皮交叉提呈[34]同免疫抑制或耐受联系起来。CD8A 只是共受体，本数据不含肽装载、T 细胞受体与空间信息，故 ESCC 中以何种结局为主无法在此判定。本段机制陈述均来自综述[31, 32]与小鼠或离体模型[30, 33, 34]，未在本队列中检验。")

L("编码 MIF–CD74 轴组分的转录本丰度较高",
  "编码 MIF–CD74 轴组分的转录本在合并分析中丰度较高，这与免疫抑制作用相容，但不能确立该作用。MIF 与 CD74 结合，生化实验显示 CD74 可与 CXCR4 形成功能性复合体[35]；CD44 亦被认为参与该受体复合物。综述指出，MIF–CD74 轴抑制 CD8 效应功能并促进髓系抑制[24]。在 ESCC 中，肿瘤细胞与肿瘤浸润淋巴细胞高表达 MIF 均与生存不良相关[36]。2026 年 Theranostics 的一项研究整合 7 套单细胞数据、192 例 ESCC 患者（含 GSE160269），结合空间转录组与多重免疫组化，提出 MIF 高表达、胆固醇合成活跃的肿瘤细胞通过 MIF–CXCR4 与 CXCL12–CXCR4 竞争，破坏三级淋巴结构内的生发中心 B 细胞反应[37]。该研究的配体来源是肿瘤细胞、靶细胞是三级淋巴结构中的 B 细胞；本文结果则是内皮与 T 细胞间合并的转录本水平配体–受体表达排序。两者并不矛盾，但本数据不能把肿瘤细胞机制外推到内皮：内皮相关 MIF 信号的细胞来源与功能后果在本数据集中仍未解决。MIF 在此处的突出地位，结合耗竭标志高表达 CD8 T 细胞的高比例（按本文定义，全部 69,278 个 T 细胞中 35.8% 至少携带两项耗竭相关标志，以多个抑制性受体转录本为特征[38]；此数据集层面占比以全部 T 细胞为分母，而相关分析所用的患者层面耗竭变量以 CD8 T 细胞为分母），与内皮参与该表型相容，但不能确立这一点。")

L("样本量与患者层面精度。",
  "样本量与患者层面精度。数据集仅含 4 例癌旁非恶性文库、856 个内皮细胞，故肿瘤与癌旁的状态比较属探索性。60 例肿瘤中有 4 例与这 4 例癌旁来自同一批患者，故主要比较采用 56 例未配对肿瘤与 4 例癌旁的精确秩和检验，并在九个状态间作 BH 校正；4 对配对样本仅报告方向，合并的 60 对 4 比较作为敏感性分析。仅有 4 对配对样本时，符号检验能达到的最小双侧 P 值为 0.125，配对设计在此没有效力。每例患者的细胞数有限（内皮细胞中位 106 个，四分位 36–216；60 例中 13 例不足 30 个），个体层面的状态占比并不精确。在主要设计下 200 次固定为每样本 20 或 30 个内皮细胞的重抽样中，静脉型、尖端样与基质重塑型差异在至少 99.5% 的重复中校正后显著，而干扰素反应性差异仅在 16% 与 85.5% 的重复中显著。bootstrap 置信区间假定 4 例癌旁文库是同一样本总体的可交换抽样，仅 4 例无法验证该假定，区间不应读作精确的总体效应范围。保留 529 细胞成纤维样簇后，主要状态的中位数差最多改变 1.9 个百分点且方向不变；处于 0.05 边界的毛细血管型判定在精确检验、保留该簇或改用主要设计时均不稳定（附表 S11、S12）。")

L("成分与分析层面的限制。",
  "成分与分析层面的限制。状态占比属成分数据，合计为 1，状态间的负相关会机械地出现：静脉–尖端系数由 −0.61 经中心对数比变换降为 −0.46，保留观测细胞数与闭合结构的 Dirichlet–多项分布零模型给出的中位系数为 −0.25 至 −0.28。观测位移虽超出该零模型（经验 P = 0.0005–0.0062），但幅度小于原始系数所示，我们不再把它解释为特定表型转换的证据。聚类亦依赖分辨率：0.4、0.6 与 0.8 下相对九状态注释的调整 Rand 指数分别为 0.80、0.68 与 0.52（附表 S8）。我们未直接检验内皮–间质转化[42]；各状态的内皮标志均保留，但不能排除部分细胞发生偏移。状态判定依赖标志基因表达与人工核查；两套独立参考（SingleR 对照 Blueprint ENCODE、CellMarker 标志集投射；附图 S1）支持九个状态的内皮来源，但均不含尖端细胞、基质相关型与干扰素反应性等肿瘤相关亚群。通讯分析主分析用 50 次置换、稳健性复核用 200 次置换；即使 200 次下多数保留配对仍 P = 0 且全部经 Benjamini-Hochberg 校正后显著，故该列表应读作「表达的配体–受体对」，单对并不获得统计学显著性支持（附表 S8）。CellChat 依配体丰度排序，不含肽装载、T 细胞受体与空间信息，不能据此证明抗原提呈。肿瘤与癌旁细胞、以及不同患者的细胞合并进入同一通讯对象，故该排序是合并的转录本水平表达谱，既不具肿瘤特异性，也不证明某配体与受体在同一患者的组织中共现。状态名称均为转录层面的描述：「干扰素反应性」不区分 I 型与 II 型干扰素信号，「候选」反映该状态稳定性有限，「尖端样」也不确立迁移或出芽表型。")

L("外部与临床层面的限制。",
  "外部与临床层面的限制。外部单细胞资源来自胃与食管–胃交界组织，含良性化生与炎症病变，不能替代额外的 ESCC 配对癌旁样本；发现队列的癌旁仍仅 4 例。各队列与状态的背景 marker 阳性率为 19.8%–93.2%，干扰素反应性状态在 GSE203067 中的 marker 层面证据方向相反，两种标签转移方法的一致率仅 48.8%，故外部比较只能作方向性参照。2026 年 Theranostics 研究[37]为肿瘤细胞来源的 MIF 提供了空间与多重免疫组化证据，但不涉及内皮来源的 MIF；本文未对九个内皮状态做独立的蛋白水平、空间或组织学正交验证。外部预后队列仅 32 个事件且违反比例风险假设，不能排除小幅效应，其风险比也不宜解读为恒定效应；评分在芯片数据上建立、在 RNA-seq 数据上应用，绝对值跨平台不可比。最后，临床注释仅限分期与 T/N/M；年龄、性别与生存未公开，无免疫治疗或抗血管治疗疗效终点队列，也未分析独立的 ESCC 配对癌旁队列。")

L("基于 4 例癌旁文库，ESCC 肿瘤与癌旁黏膜在内皮状态构成上存在差异",
  "基于 4 例癌旁非恶性文库、且主要比较限定于 56 例未配对肿瘤，ESCC 肿瘤与癌旁黏膜在内皮状态构成上存在差异：静脉型占比降低，尖端样与基质重塑型占比升高。候选、探索性干扰素反应性状态表达编码 CXCL9、CXCL10 与 CXCL11 的转录本，但稳定性低于前两者。合并的转录本水平内皮–T 细胞配体–受体表达分析以 MHC I 类与 MIF 丰度最高，黏附分子贡献很小；该排序不构成肿瘤特异通讯、抗原提呈或任何功能的证据。尖端细胞来源的转录本可区分肿瘤与癌旁组织，但匹配的随机基因集同样可以，且评分与状态占比均不预测生存。外部队列支持构成改变的方向，但不支持绝对比例。第二队列中同样阴性的预后结果未改变这一定位。这些观察属描述性与假说生成性质；要确立其在免疫分层或抗血管疗效预测中的作用，需要带治疗终点的队列与正交验证，本研究不提供此类证据。")

L("**数据可得性。**",
  "**数据可得性。**本文分析的数据集均公开可得：GSE160269、GSE53625、GSE20347、GSE45670 与 GSE225178 可从 Gene Expression Omnibus 获取（https://www.ncbi.nlm.nih.gov/geo/）。另有三套公开单细胞资源用于方向性外部支持：GSE196756[43]、GSE203067[44] 与 Nowicki-Osuch 食管–胃图谱的 CELLxGENE 内皮子集[45]；处理后的目标基因矩阵、状态质心与全部数值输出见附表 S9。跨平台预后复核所用 TCGA-ESCA 表达、临床与生存文件来自 UCSC Xena（tcga.xenahubs.net），其底层 TCGA 食管癌队列的分子图谱见文献[46]，复核输出见附表 S10。附表 S11 收录逐一剔除癌旁样本、保留成纤维样簇、精确检验、Hodges–Lehmann 效应量与 bootstrap 敏感性分析；附表 S12 收录配对/非配对统计设计重算、精确检验对照与分析脚本清单。全部数值输出已包含在正文与补充材料（附表 S1–S12、附图 S1–S4）中，各附表另以独立文件提供。分析脚本与处理后对象可向通讯作者合理索取；其他询问亦请联系通讯作者。")

L("**人工智能使用声明。**",
  "**人工智能使用声明。**作者在文稿准备过程中使用生成式人工智能助手（腾讯混元大模型，模型标识 Hy，由腾讯开发，经 WorkBuddy 桌面应用访问，workbuddy.cn；访问界面未提供数字版本号；2026 年 11 月 2 日至 9 日期间访问）协助文字起草、语言润色及表格与图注的排版；该工具未用于生成数据、统计结果、图像或参考文献，全部分析由作者使用「材料与方法」所列软件完成，作者对每一处 AI 辅助文字均对照原始分析结果与引用文献逐句核查，并对内容的准确性、原创性与完整性承担全部责任。")

